DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_1','Token Network[NEWLINE]A shared resource economy with selectable tactical and economic tools[NEWLINE]Science; flexible Culture, Diplomacy or supported Domination[NEWLINE][NEWLINE]Grow Token income and capacity, then buy the effect that matters to the current plan. A large balance is useful only if the selected Prompt, target, persistent slot and saturation cost all fit the next few turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_2','Support population and productive cities while accumulating a reserve. Use an early instant grant where it advances an important real order, and retain enough resources for an unexpected defense. Instant grants stop short of completing the item or technology.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_3','Develop specialist cities and Inference infrastructure. Coordinate repeated Prompt types with Cached Responses, but do not refresh an unhelpful effect merely to keep a discount. Persistent target-specific effects still consume the appropriate limited slots.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_4','Use higher models and capacity to support a deliberate research, economic or military timing. Check the spending tier before stacking purchases. Clear Context is an emergency reset of balance and effects, not a way to remove saturation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_5','- One income system can fund several different strategic responses.[NEWLINE]- Infrastructure and specialists expand both generation and late capacity.[NEWLINE]- Caching and later models can make a coherent repeated plan more efficient.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_6','- Persistent slots and a shared balance limit simultaneous answers.[NEWLINE]- Heavy spending reduces subsequent generation through saturation.[NEWLINE]- Capacity loss can discard overflow, and Clear Context removes active persistent benefits and cache.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_7','- Create threats on several fronts so one budget and a few slots cannot answer everything.[NEWLINE]- Bait an expensive response, disengage, and attack while resources or generation are strained.[NEWLINE]- Threaten specialist and inference cities that support capacity and income.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_8','- Expecting instant Production or research grants to finish the current item themselves.[NEWLINE]- Assuming Clear Context removes saturation or per-turn action limits.[NEWLINE]- Buying a strong buff too early for its short duration to affect the real battle.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Paid movement and selectable unit support can help a threatened Project target withdraw or change the terms of an engagement.[NEWLINE][NEWLINE]Terra: Prompt choice can respond directly to a current emergency while Terra''s strongest local Mode is tied to its construction plan.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Several expanding production fronts can force competing demands on a single Token reserve.[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption and a well-timed shutdown can force defensive spending just when saturation makes recovery harder.');
