INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_LEADER_TEXT_2','Support population and productive cities while accumulating a reserve. Use an early instant grant where it advances an important real order, and retain enough resources for an unexpected defense. Instant grants stop short of completing the item or technology.[NEWLINE][NEWLINE]Develop specialist cities and Inference infrastructure. Coordinate repeated Prompt types with Cached Responses, but do not refresh an unhelpful effect merely to keep a discount. Persistent target-specific effects still consume the appropriate limited slots.[NEWLINE][NEWLINE]Use higher models and capacity to support a deliberate research, economic or military timing. Check the spending tier before stacking purchases. Clear Context is an emergency reset of balance and effects, not a way to remove saturation.');
