INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_TOKENIZEDINTELLIGENCE_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Capano Circuit: Paid movement and selectable unit support can help a threatened Project target withdraw or change the terms of an engagement.[NEWLINE][NEWLINE]Terra: Prompt choice can respond directly to a current emergency while Terra''s strongest local Mode is tied to its construction plan.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Luna Network: Several expanding production fronts can force competing demands on a single Token reserve.[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption and a well-timed shutdown can force defensive spending just when saturation makes recovery harder.');
